// Verus program for copying a Vec<u64> of length at most 100

verus! {

    fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
        requires a.len() <= 100
        ensures  b.len() == a.len()
        ensures  forall |i: usize| i < a.len() ==> b[i] == a[i]
    {
        let mut b: Vec<u64> = Vec::new();
        let mut i: usize = 0;
        while i < a.len()
            invariant  i <= a.len()
            invariant  b.len() == i
            invariant  forall |j: usize| j < i ==> b[j] == a[j]
            decreases a.len() - i
        {
            b.push(a[i]);
            i += 1;
        }
        b
    }

}